    private static readonly Dictionary<string, Dictionary<string, string>> Languages =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["en-US"] = EnUS,
            ["zh-CN"] = ZhCN,
            ["zh-TW"] = ZhTW,
            ["tr-TR"] = TrTR,
            ["ru-RU"] = RuRU,
            ["pt-BR"] = PtBR,
            ["de-DE"] = DeDE,
            ["fr-FR"] = FrFR,
            ["uk-UA"] = UkUA,
            ["it-IT"] = ItIT,
            ["es-ES"] = EsES,
            ["ko-KR"] = KoKR,
            ["vi-VN"] = ViVN,
        };

    public static bool TryGet(string language, string key, [NotNullWhen(true)] out string? value)
    {
        if (Languages.TryGetValue(language, out var table) && table.TryGetValue(key, out value))
        {
            return true;
        }

        value = null;
        return false;
    }
}
